#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_autop;
uniform float amzp_freq;
uniform float amzp_SPEED;
uniform float amzp_LGT;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) { return a * (1.0 - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.0)*amzLayerToScreen()).xy; }
        float rand(float2 co){
            return fract(sin(dot(co.xy ,float2(12.9898,78.233))) * 43758.5453);
        }
        float sdUnevenCapsule( in float2 p, in float2 a, in float2 b, in float r1, in float r2 )
        {
            float2 pa = p-a, ba = b-a;
            float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
            return length( pa - ba*h ) - mix(r1, r2, h);
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float iTime = time;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((-180.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0-amzp_position.x), (-100.0+amzp_position.y))*float2(-1.,1.0)/500.0;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
            float2 uv = satriyaid;
            float my_iTime = amzp_SPEED;
            float NEWFREQ = (amzp_autop>0.5)? amzp_freq + (time*1.5) : amzp_freq;
            float t_base = floor(NEWFREQ * my_iTime);
         float t_off = 1.0 * rand(float2(t_base, 134.0)) / amzp_freq;
            my_iTime += t_off;
            t_base += t_off;
            float2 amzLocal_pos = float2(1.0 * (2.0 * rand(float2(t_base, 995.0)) - 1.0),
                            1.0 + 0.2 * (2.0 * rand(float2(t_base, 46.0)) - 1.0));
            float r = 0.03;
            float a = radians(270.0) + radians(45.0) * (2.0 * rand(float2(t_base, 13.0)) - 1.0);
            float d = 1e10;
            float sum_len = 0.0;
            float t = 1.0;
            float len_max = 8.0 * t;
            float2 branch_1_pos;
            float branch_1_len = 0.0;
            float branch_1_r = 0.0;
         float branch_1_a;
         float2 branch_2_pos;
            float branch_2_len = 0.0;
            float branch_2_r = 0.0;
         float branch_2_a;
            for (int i = 0; i < int(amzp_LGT); ++i) {
                if (sum_len >= len_max)
                    break;
                if (i == 3) {
                    branch_1_pos = amzLocal_pos;
                    branch_1_len = sum_len;
                    branch_1_r = 0.5 * r;
                    branch_1_a = radians(270.0) + radians(90.0) * (2.0 * rand(float2(t_base, 13.0)) - 1.0);
                }
          if (i == 6) {
                    branch_2_pos = amzLocal_pos;
                    branch_2_len = sum_len;
                    branch_2_r = 0.5 * r;
                    branch_2_a = radians(270.0) - radians(90.0) * (2.0 * rand(float2(t_base, 17.0)) - 1.0);
                }
                float len = (amzp_LGT*0.01) + 0.18 * rand(float2(300.0 + float(i) + t_base, 1337.0));
                float a_next = mix(a, radians(270.0) + radians(40.0) * (2.0 * rand(float2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.9);
          float2 next = amzLocal_pos + len * float2(cos(a), sin(a));
                float r_next = 0.9 * r;
             d = min(d, sdUnevenCapsule(uv,
                                           amzLocal_pos, next,
                                           r, r_next));
                amzLocal_pos = next;
                r = r_next;
                a = a_next;
                sum_len = sum_len + len;
         }
            for (int i = 0; i < 10; ++i) {
                if (branch_1_len >= len_max)
                    break;
          float len = 0.07 + 0.07 * rand(float2(300.0 + float(i) + t_base, 1337.0));
                float a_next = mix(radians(270.0), branch_1_a + radians(40.0) * (2.0 * rand(float2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.5);
          float2 next = branch_1_pos + len * float2(cos(branch_1_a), sin(branch_1_a));
                float r_next = 0.9 * branch_1_r;
                d = min(d, sdUnevenCapsule(uv, branch_1_pos, next, branch_1_r, r_next));
          branch_1_pos = next;
                branch_1_r = r_next;
                branch_1_a = a_next;
                branch_1_len += len;
            }
            for (int i = 0; i < 10; ++i) {
                if (branch_2_len >= len_max)
                    break;
          float len = 0.07 + 0.07 * rand(float2(300.0 + float(i) + t_base, 1337.0));
                float a_next = mix(radians(270.0), branch_2_a + radians(40.0) * (2.0 * rand(float2(float(300 * i) + t_base, 1337.0)) - 1.0), 0.5);
          float2 next = branch_2_pos + len * float2(cos(branch_2_a), sin(branch_2_a));
                float r_next = 0.9 * branch_2_r;
                d = min(d, sdUnevenCapsule(uv, branch_2_pos, next, branch_2_r, r_next));
          branch_2_pos = next;
                branch_2_r = r_next;
                branch_2_a = a_next;
                branch_2_len += len;
            }
            float3 sky =
                  0.2 * float3(0, 0, 1) * clamp(sum_len, 0., 1.0)
                + 0.1 * float3(1, 1, 1) * clamp(sum_len - 0.8, 0., 1.0);
            fragColor = float4(sky
                             + clamp(0.9 - sqrt(d + 0.01), 0., 1.0) * sky * max(0.9 * uv.y + 2., 0.0)
                             + float3(smoothstep(0.0, -.01, d)), 1.0);
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(amzp_color1,amzp_color2,luminance)*fragColor.a;
         float4 factor = mix(texColorX,gradmap,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.0)*(1.0-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
